from sympy import primerange, isprime, factorial
from math import gcd

def P(n):
    primes = list(primerange(2, n+1))
    prod = 1
    for i in range(len(primes)):
        for j in range(i+1, len(primes)):
            prod *= (primes[i]+primes[j])
    return prod

def check(n):
    p = P(n)
    f = factorial(n)
    return p % f == 0, p, f

for n in range(3, 40):
    ok, p, f = check(n)
    if ok:
        print(f'n={n}: YES  P/P! ratio = {p//f}')
    else:
        print(f'n={n}: no')
