from sympy import primerange, isprime, factorial, factorint

# For each n, find which prime ell causes failure (the bottleneck)
def analyze(n):
    primes = list(primerange(2, n+1))
    # compute v_ell(P(n)) for each prime ell <= n
    from collections import defaultdict
    vP = defaultdict(int)
    for i in range(len(primes)):
        for j in range(i+1, len(primes)):
            s = primes[i]+primes[j]
            for ell in primerange(2, n+1):
                while s % ell == 0:
                    vP[ell] += 1
                    s //= ell
    # v_ell(n!)
    def vfact(n, ell):
        v = 0
        pk = ell
        while pk <= n:
            v += n // pk
            pk *= ell
        return v
    worst = []
    for ell in primerange(2, n+1):
        vn = vfact(n, ell)
        if vP[ell] < vn:
            worst.append((ell, vP[ell], vn))
    return worst

for n in [7, 8, 9, 10, 11, 13, 17, 19, 23, 29, 31, 37]:
    w = analyze(n)
    if w:
        print(f'n={n}: FAIL primes: {w[:5]}')
    else:
        print(f'n={n}: OK')
