from sympy import primerange, isprime
from collections import defaultdict

# Faster: only check large primes (ell > n/2) since those are the bottleneck
def check_fast(n):
    primes = list(primerange(2, n+1))
    primes_set = set(primes)
    # For each prime ell in (n/2, n], check if ell divides some (p+q)
    large_primes = [p for p in primes if p > n/2]
    for ell in large_primes:
        found = False
        # Check p+q = ell, 2*ell, 3*ell (if <= 2*n-2)
        for target in [ell, 2*ell, 3*ell]:
            if target > 2*n - 2:
                continue
            if target < 5:
                continue
            # target = p + q, p < q, both prime, q <= n
            # q ranges from max(target-n, 2) to min(n, target-2), q > target/2
            qmin = max(target - n, 2)
            qmax = min(n, target - 2)
            for q in range(max(qmin, target//2 + 1), qmax + 1):
                p = target - q
                if p >= 2 and p < q and p in primes_set and q in primes_set:
                    found = True
                    break
            if found:
                break
        if not found:
            return False, ell
    # Also check small primes (2 and 3) for n=8,9,10
    # Actually let's just check all primes properly for small n
    if n <= 12:
        vP = defaultdict(int)
        for i in range(len(primes)):
            for j in range(i+1, len(primes)):
                s = primes[i]+primes[j]
                for ell in primerange(2, n+1):
                    while s % ell == 0:
                        vP[ell] += 1
                        s //= ell
        def vfact(n, ell):
            v = 0; pk = ell
            while pk <= n:
                v += n // pk; pk *= ell
            return v
        for ell in primerange(2, n+1):
            if vP[ell] < vfact(n, ell):
                return False, ell
    return True, None

for n in range(120, 500):
    ok, bad = check_fast(n)
    if ok:
        print(f'n={n}: YES')
print('done up to 499')
