from sympy import primerange, isprime

# Key idea: for prime ell ≡ 2 (mod 3) in (2n/3, n], ell-2 ≡ 0 (mod 3) and > 3, so not prime.
# Also all primes q in (ell, n] are ≡ 1 (mod 3), so 2*ell - q ≡ 0 (mod 3) and > 3, composite.
# So such ell is a witness. Question: does such ell always exist for n >= 11?

def largest_prime_2mod3(n):
    for p in range(n, 1, -1):
        if isprime(p) and p % 3 == 2:
            return p
    return None

for n in range(11, 200):
    ell = largest_prime_2mod3(n)
    if ell is None or ell <= 2*n/3:
        print(f'n={n}: largest prime ≡2(mod3) = {ell}, 2n/3 = {2*n/3:.2f}, FAILS the condition')
print('done')
"

